Read all employee/month/hours rows from the active sheet and index them by employee and calendar month. For each answer row, sum the hours for that employee in the current month and the three preceding calendar months, writing `n/a` if fewer than four distinct months exist. Write the average as an integer when it is whole, otherwise as a number, into E2:E25.

```python
import shutil
import re
import datetime
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws = vals.active
ws = wb[vws.title]

def parse_ym(value):
    if value is None:
        return None
    if isinstance(value, (datetime.datetime, datetime.date)):
        return (value.year, value.month)

    s = str(value).strip()
    if not s:
        return None

    m = re.match(r"^(\d{4})[-/](\d{1,2})", s)
    if m:
        return (int(m.group(1)), int(m.group(2)))

    m = re.match(r"^(\d{4})(\d{2})$", s)
    if m:
        return (int(m.group(1)), int(m.group(2)))

    return None

def emp_key(value):
    if value is None:
        return None
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value).strip()

def add_months(ym, delta):
    y, m = ym
    m0 = m + delta - 1
    y += m0 // 12
    m = m0 % 12 + 1
    return (y, m)

def format_average(x):
    x = round(x, 2)
    if abs(x - round(x)) < 1e-9:
        return int(round(x))
    return x

records = {}
for r in range(2, vws.max_row + 1):
    emp = vws.cell(r, 1).value
    if emp is None:
        continue

    key = emp_key(emp)
    ym = parse_ym(vws.cell(r, 3).value)
    if ym is None:
        ym = parse_ym(vws.cell(r, 2).value)
    if ym is None:
        continue

    hours = vws.cell(r, 4).value
    try:
        hours = float(hours)
    except (TypeError, ValueError):
        hours = 0.0

    records.setdefault(key, []).append((ym, hours))

for r in range(2, 26):
    emp = vws.cell(r, 1).value
    if emp is None:
        ws.cell(r, 5).value = None
        continue

    key = emp_key(emp)
    ym = parse_ym(vws.cell(r, 3).value)
    if ym is None:
        ym = parse_ym(vws.cell(r, 2).value)
    if ym is None:
        ws.cell(r, 5).value = None
        continue

    window = {add_months(ym, -i) for i in range(4)}
    month_totals = {}

    for ym2, h in records.get(key, []):
        if ym2 in window:
            month_totals[ym2] = month_totals.get(ym2, 0.0) + h

    if len(month_totals) < 4:
        val = "n/a"
    else:
        val = format_average(sum(month_totals.values()) / 4.0)

    ws.cell(r, 5).value = val
    print(r, key, ym, len(month_totals), val)

wb.save(OUT)
